from math import erf, exp, log, pi, sqrt

def phi(z):
    return exp(-z * z / 2) / sqrt(2 * pi)

def Phi(z):
    return 0.5 * (1 + erf(z / sqrt(2)))

def bs_greeks(S, K, sigma, T, places=4):
    """[delta, gamma, vega per vol point, theta per trading day]
    for a call at r = 0, rounded to `places`."""
    d1 = (log(S / K) + sigma * sigma * T / 2) / (sigma * sqrt(T))
    delta = Phi(d1)
    gamma = phi(d1) / (S * sigma * sqrt(T))  # phi(d1) / (S * sigma * sqrt(T))
    vega = gamma * S * S * sigma * T / 100  # gamma * S^2 * sigma * T, divided by 100
    theta = -0.5 * sigma * sigma * S * S * gamma / 252  # -0.5 * sigma^2 * S^2 * gamma, divided by 252
    return [round(x, places) for x in (delta, gamma, vega, theta)]

def net_greeks(legs, S, sigma):
    """legs: (kind, K, T, qty) with kind 'call' or 'put'. A put's delta
    is the call's delta minus 1; its other Greeks equal the call's."""
    total = [0.0, 0.0, 0.0, 0.0]
    for kind, K, T, qty in legs:
        g = bs_greeks(S, K, sigma, T, 12)
        if kind == "put":
            g[0] -= 1
        for i in range(4):
            total[i] += qty * g[i]
    return [round(x, 4) for x in total]
